function [s, vval, vperf] = loop_option_violation(vval, vperf, v0, v1, perf_only)
%LOOP_OPTION_VIOLATION  An option's violation: the sum of its violations vval[v0 .. v1] (those flagged in perf only, when perf_only), from 0.
%   length: 16
%   vval: inout real[1][*] (passed a plain number)
%   vperf: inout int[*] (passed a whole number)
%   v0: int (passed a whole number)
%   v1: int (passed a whole number)
%   perf_only: bool (passed true or false)
%   returns s: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    s = 0;
    s = 0;
    for i = (v0):((asils.pc.fmin(v1, numel(vval))) - 1)
        if ((~perf_only) || (vperf((i) + 1) == 1))
            s = (s + vval((i) + 1));
        end
    end
end
